            if (value !== undefined && value !== null) {
              element.setAttribute(name, value);
            }
          });
        }
        return element;
      };

      const FormField = ({
        id,
        label,
        type = "text",
        autocomplete,
        required = false,
        helperText = "",
        placeholder = "",
        inputMode,
      }) => {
        const wrapper = createElement("div", { className: "form-field" });
        const labelElement = createElement("label", { attributes: { for: id } });
